insert into public.activities
  (slug, title, short_description, description, min_age, max_age, duration, category, location, materials, material_tags, adult_help, preparation, steps, tip, premium)
values
  ('burbujas-de-jabon', 'Burbujas de jabón', 'Tú haces burbujas, él las persigue y las revienta.', 'Prepara agua con jabón y haz burbujas para que tu hijo corra a atraparlas.', 2, 4, 15, 'moverse', 'afuera', array['jabón líquido', 'agua', 'un vaso', 'un aro de alambre o un pitillo']::text[], array['nada']::text[], true, '2 minutos.', array['Mezcla un poco de jabón con agua en el vaso.', 'Sopla tú las burbujas.', 'Que corra a reventarlas con las manos.', 'Cuenten juntos cuántas alcanza a atrapar.']::text[], 'A esta edad sopla tú: así no traga agua con jabón.', true),
  ('pintar-con-agua', 'Pintar con agua', 'Una brocha, un vaso de agua y una pared que se pinta y se borra.', 'Con una brocha y agua, tu hijo pinta el piso o una pared exterior. El dibujo desaparece solo y vuelve a empezar.', 2, 4, 15, 'crear', 'afuera', array['una brocha o pincel grueso', 'un vaso con agua']::text[], array['nada']::text[], false, '1 minuto.', array['Llena el vaso con agua.', 'Dale la brocha y muéstrale cómo mojar el piso.', 'Que pinte rayas, círculos o lo que quiera.', 'Miren cómo se borra el dibujo al secarse.']::text[], 'Funciona perfecto en un patio, un balcón o la entrada de la casa.', true),
  ('torre-de-vasos', 'Torre de vasos', 'Apilar, apilar y ¡pum!, tumbar.', 'Apilen vasos plásticos para hacer torres y tumbarlas. Es simple y les encanta repetirlo.', 2, 3, 5, 'aprender', 'casa', array['6 a 10 vasos plásticos']::text[], array['nada']::text[], false, 'Nada.', array['Pon los vasos en el piso.', 'Muéstrale cómo poner uno encima de otro.', 'Que construya la torre más alta que pueda.', 'Cuando la tumbe, celébrenlo y vuelvan a empezar.']::text[], 'Cuenten los vasos en voz alta mientras apila.', true),
  ('cesta-de-medias', 'Cesta de medias', 'Medias enrolladas como pelotas y una canasta para encestar.', 'Enrolla medias como pelotas y que tu hijo intente meterlas en una canasta.', 2, 4, 5, 'moverse', 'casa', array['medias limpias enrolladas', 'una canasta o caja']::text[], array['nada']::text[], false, '1 minuto.', array['Enrolla 5 o 6 pares de medias.', 'Pon la canasta a un paso de distancia.', 'Que lance las medias para encestar.', 'Aléjala un poco cada vez que acierte.']::text[], 'Las medias no hacen daño ni rompen nada: ideal para jugar adentro.', true),
  ('caras-en-el-espejo', 'Caras en el espejo', 'Feliz, triste, sorprendido: hacer caras frente al espejo.', 'Frente a un espejo, hagan caras de distintas emociones y pónganles nombre.', 2, 4, 5, 'tranquilo', 'casa', array['un espejo']::text[], array['nada']::text[], true, 'Nada.', array['Siéntense juntos frente al espejo.', 'Haz una cara feliz y dile: así me veo feliz.', 'Que te imite.', 'Sigan con triste, enojado, sorprendido y dormido.']::text[], 'Nombrar las emociones les ayuda a reconocerlas en ellos mismos.', true),
  ('maracas-de-botella', 'Maracas de botella', 'Una botella, un puñado de arroz y música.', 'Hagan maracas con botellas plásticas y granos secos, y toquen al ritmo de una canción.', 2, 4, 15, 'crear', 'casa', array['una botella plástica pequeña con tapa', 'arroz o frijoles', 'cinta']::text[], array['cinta']::text[], true, '3 minutos.', array['Echa un puñado de arroz dentro de la botella.', 'Cierra bien la tapa y séllala con cinta.', 'Que la sacuda fuerte y suave.', 'Pongan una canción y toquen juntos.']::text[], 'Tú cierras y sellas la botella: los granos son pequeños y no deben salir.', true),
  ('despegar-cintas', 'Despegar cintas', 'Tiras de cinta pegadas en una bandeja para despegar una a una.', 'Pega tiras de cinta en una bandeja o mesa y que tu hijo las despegue con sus dedos.', 2, 3, 15, 'aprender', 'casa', array['cinta de enmascarar', 'una bandeja o la mesa']::text[], array['cinta']::text[], false, '2 minutos.', array['Pega 10 tiras de cinta en la bandeja.', 'Dobla una puntica de cada una para que sea fácil empezar.', 'Que las despegue una por una.', 'Pueden pegarlas después en una hoja.']::text[], 'Es un gran ejercicio para los dedos y lo mantiene concentrado.', true),
  ('paseo-de-peluches', 'Paseo de peluches', 'Una caja se vuelve carro para pasear a los peluches.', 'Una caja de cartón se convierte en carro, y tu hijo lleva a sus peluches de paseo por la casa.', 2, 4, 15, 'juntos', 'casa', array['una caja de cartón', 'peluches']::text[], array['carton']::text[], false, '1 minuto.', array['Pon los peluches dentro de la caja.', 'Que la empuje por la casa.', 'Paren en cada cuarto para que los peluches conozcan.', 'Al final, acuesten a los peluches a dormir.']::text[], 'Pregúntale a dónde van y quién va manejando.', true),
  ('canciones-con-gestos', 'Canciones con gestos', 'Cantar y mover el cuerpo al mismo tiempo.', 'Canten canciones infantiles de siempre haciendo los gestos con las manos y el cuerpo.', 2, 4, 5, 'juntos', 'cualquier', '{}'::text[], array['nada']::text[], false, 'Nada.', array['Elige una canción que se sepan, como Cabeza, hombros, rodillas y pies.', 'Cántala despacio haciendo los gestos.', 'Repítela un poco más rápido.', 'Que él escoja la siguiente.']::text[], 'Perfecto para la fila, el carro o la sala de espera.', true),
  ('el-tunel', 'El túnel', 'Una cobija sobre dos sillas y a gatear.', 'Arma un túnel con sillas y una cobija para que tu hijo gatee de un lado al otro.', 2, 4, 15, 'moverse', 'casa', array['2 o 3 sillas', 'una cobija']::text[], array['nada']::text[], true, '2 minutos.', array['Pon las sillas en fila, con un espacio en medio.', 'Cúbrelas con la cobija.', 'Espéralo al otro lado del túnel.', 'Que entre gateando y salga a tus brazos.']::text[], 'Pon un peluche al final del túnel como premio.', true),
  ('bolas-de-papel', 'Bolas de papel', 'Arrugar papel y lanzarlo a una caja.', 'Arruguen hojas de papel periódico para hacer bolas y lancénlas a una caja.', 2, 4, 5, 'crear', 'casa', array['papel periódico o hojas viejas', 'una caja']::text[], array['papel']::text[], false, 'Nada.', array['Muéstrale cómo arrugar una hoja hasta hacerla bola.', 'Que haga varias.', 'Pon la caja cerca y lancen las bolas.', 'Al final, recojan todo juntos.']::text[], 'Arrugar papel también fortalece las manos.', true),
  ('donde-esta', '¿Dónde está?', 'Un juguete escondido bajo uno de tres vasos.', 'Esconde un juguete pequeño bajo uno de tres vasos y que tu hijo adivine dónde está.', 2, 4, 5, 'aprender', 'casa', array['3 vasos que no sean transparentes', 'un juguete pequeño']::text[], array['nada']::text[], false, 'Nada.', array['Muéstrale el juguete.', 'Escóndelo bajo un vaso mientras te mira.', 'Mueve los vasos despacio.', 'Que levante el vaso donde cree que está.']::text[], 'Al principio no muevas los vasos: solo escóndelo y que lo encuentre.', true),
  ('masa-casera', 'Masa casera', 'Plastilina hecha en casa con harina, sal y agua.', 'Preparen juntos una masa suave para amasar, aplastar y hacer figuras.', 2, 5, 30, 'crear', 'casa', array['2 tazas de harina', '1 taza de sal', 'agua', 'colorante de alimentos opcional']::text[], array['plastilina']::text[], true, '5 minutos.', array['Mezclen la harina y la sal en un platón.', 'Agrega agua poco a poco mientras amasan.', 'Si quieren, agrega unas gotas de colorante.', 'Hagan bolitas, culebras y figuras.']::text[], 'Guarda la masa en una bolsa cerrada y dura varios días.', true),
  ('collares-de-pasta', 'Collares de pasta', 'Pasta en tubitos y una lana para ensartar.', 'Ensarten pasta en forma de tubo en una lana para hacer collares y pulseras.', 3, 5, 30, 'crear', 'casa', array['pasta en tubitos (penne)', 'lana o cordón', 'cinta']::text[], array['cinta']::text[], true, '2 minutos.', array['Envuelve una punta de la lana con cinta para que quede dura.', 'Haz un nudo grande en la otra punta.', 'Que ensarte la pasta una por una.', 'Amarra el collar y que se lo ponga.']::text[], 'Si quieren color, pinten la pasta con marcadores antes.', true),
  ('formas-en-el-piso', 'Formas en el piso', 'Círculo, cuadrado y triángulo de cinta para saltar.', 'Pega formas con cinta en el piso. Tú dices una forma y tu hijo salta adentro.', 3, 5, 15, 'aprender', 'casa', array['cinta de enmascarar']::text[], array['cinta']::text[], false, '3 minutos.', array['Pega en el piso un círculo, un cuadrado y un triángulo.', 'Dile el nombre de cada forma.', 'Grita una forma y que salte dentro.', 'Después que él te dé las órdenes a ti.']::text[], 'Agrega colores: salta al círculo con el pie derecho.', true),
  ('calcar-hojas', 'Calcar hojas', 'Una hoja de árbol bajo el papel y aparece su dibujo.', 'Pon hojas de árbol bajo una hoja de papel y pasen un crayón por encima para que aparezcan las nervaduras.', 3, 5, 15, 'crear', 'cualquier', array['hojas de árbol', 'papel', 'crayones']::text[], array['papel', 'colores']::text[], false, 'Recoger las hojas, 5 minutos.', array['Recojan hojas de distintas formas en el parque o el patio.', 'Pon una hoja debajo del papel.', 'Que pase el crayón acostado por encima.', 'Repitan con otras hojas y colores.']::text[], 'Las hojas frescas y con venas marcadas se ven mejor.', true),
  ('lavadero-de-juguetes', 'Lavadero de juguetes', 'Agua, jabón y juguetes sucios para bañar.', 'Llenen un platón con agua y jabón y laven juntos los juguetes plásticos.', 3, 5, 15, 'juntos', 'casa', array['un platón con agua tibia', 'jabón', 'una esponja', 'juguetes plásticos', 'una toalla']::text[], array['nada']::text[], true, '3 minutos.', array['Pon el platón sobre una toalla.', 'Que meta los juguetes en el agua.', 'Que los frote con la esponja.', 'Pónganlos a secar en fila sobre la toalla.']::text[], 'Quédate a su lado mientras haya agua.', true),
  ('carrera-de-animales', 'Carrera de animales', 'Saltar como rana, caminar como pato, arrastrarse como serpiente.', 'Hagan carreras cortas imitando cómo se mueven distintos animales.', 3, 5, 5, 'moverse', 'cualquier', '{}'::text[], array['nada']::text[], false, 'Nada.', array['Marca una salida y una meta.', 'Di un animal: rana.', 'Que llegue a la meta saltando como rana.', 'Sigan con pato, cangrejo, oso y serpiente.']::text[], 'Que él invente el siguiente animal.', true),
  ('ropa-por-colores', 'Ropa por colores', 'Separar la ropa limpia en montoncitos de colores.', 'Pídele ayuda para separar la ropa limpia por colores antes de doblarla.', 3, 5, 15, 'aprender', 'casa', array['ropa limpia']::text[], array['nada']::text[], false, 'Nada.', array['Riega la ropa limpia sobre la cama.', 'Que haga un montón por cada color.', 'Pregúntale de qué color es cada montón.', 'Busquen juntos la ropa de cada persona.']::text[], 'Le hace sentir que ayuda de verdad en la casa.', true),
  ('mi-silueta', 'Mi silueta', 'Acostarse en un papel grande y dibujar su contorno.', 'Dibuja el contorno del cuerpo de tu hijo sobre papel grande y que él lo decore.', 3, 5, 30, 'crear', 'casa', array['papel grande o varias hojas unidas con cinta', 'marcadores']::text[], array['papel', 'colores', 'cinta']::text[], true, '3 minutos.', array['Une hojas con cinta hasta que quepa acostado.', 'Que se acueste encima y dibuja su contorno.', 'Que le dibuje la cara, la ropa y el pelo.', 'Péguenla en la pared de su cuarto.']::text[], 'Guárdala y repítanla en un año para ver cuánto creció.', true),
  ('el-tren-de-sillas', 'El tren de sillas', 'Sillas en fila, boletos de papel y a viajar.', 'Pongan sillas en fila como un tren y viajen a lugares imaginarios.', 3, 5, 15, 'juntos', 'casa', array['sillas', 'papel para boletos']::text[], array['papel']::text[], false, '2 minutos.', array['Pongan las sillas una detrás de otra.', 'Hagan boletos en papel.', 'Uno es el conductor y otro revisa los boletos.', 'Anuncien cada parada: la playa, el zoológico, la casa de la abuela.']::text[], 'Suban peluches como pasajeros.', true),
  ('pesca-de-tapas', 'Pesca de tapas', 'Tapas flotando y una cuchara para sacarlas.', 'Pon tapas en un platón con agua y que tu hijo las pesque con una cuchara.', 3, 5, 15, 'aprender', 'casa', array['un platón con agua', 'tapas plásticas', 'una cuchara', 'un vaso']::text[], array['nada']::text[], true, '2 minutos.', array['Pon el platón con agua sobre una toalla.', 'Echa las tapas en el agua.', 'Que las saque con la cuchara y las ponga en el vaso.', 'Cuenten cuántas pescó.']::text[], 'Quédate a su lado mientras haya agua.', true),
  ('banda-de-ollas', 'Banda de ollas', 'Ollas, cucharas de palo y un concierto en la cocina.', 'Ollas y cucharas de palo se convierten en tambores para hacer música.', 3, 5, 15, 'crear', 'casa', array['ollas y tapas', 'cucharas de palo']::text[], array['nada']::text[], false, '1 minuto.', array['Pon las ollas boca abajo en el piso.', 'Dale dos cucharas de palo.', 'Que toque fuerte y luego suave.', 'Imiten ritmos por turnos.']::text[], 'Avísale a los vecinos o hazlo a media mañana.', true),
  ('que-animal-soy', '¿Qué animal soy?', 'Imitar un animal sin hablar y adivinar.', 'Por turnos, imiten un animal con gestos y sonidos y el otro adivina cuál es.', 3, 5, 5, 'juntos', 'cualquier', '{}'::text[], array['nada']::text[], false, 'Nada.', array['Empieza tú imitando un animal sin decir su nombre.', 'Que adivine qué animal eres.', 'Cambien el turno.', 'Sumen pistas si es difícil: vive en el agua.']::text[], 'Sirve para esperas en el médico o en el carro.', true),
  ('sellos-de-esponja', 'Sellos de esponja', 'Esponjas recortadas en formas para estampar.', 'Recorta esponjas de cocina en formas y úsenlas como sellos con pintura.', 3, 5, 15, 'crear', 'casa', array['esponjas de cocina nuevas', 'tijeras', 'témperas', 'papel', 'un plato']::text[], array['papel', 'colores']::text[], true, '5 minutos.', array['Recorta la esponja en círculo, cuadrado o estrella.', 'Pon un poco de pintura en un plato.', 'Que moje la esponja y estampe en el papel.', 'Combinen formas y colores.']::text[], 'Protege la mesa con papel periódico.', true),
  ('flores-de-papel', 'Flores de papel', 'Un jardín de papel para pegar en la pared.', 'Recorten y armen flores de papel de colores para decorar la casa.', 3, 5, 30, 'crear', 'casa', array['papel de colores', 'tijeras de punta roma', 'cinta']::text[], array['papel', 'cinta']::text[], true, '2 minutos.', array['Dibuja círculos para los pétalos y que los recorte.', 'Peguen los pétalos alrededor de un círculo amarillo.', 'Hagan un tallo con una tira verde.', 'Peguen las flores en la pared con cinta.']::text[], 'Si recortar le cuesta, que rasgue el papel con los dedos.', true),
  ('caja-de-texturas', 'Caja de texturas', 'Suave, áspero, frío y liso: tocar y comparar.', 'Reúnan objetos de distintas texturas y descríbanlos tocándolos con los ojos cerrados.', 3, 5, 15, 'aprender', 'casa', array['objetos de distintas texturas: algodón, lija, una piedra, una cuchara']::text[], array['nada']::text[], true, '3 minutos.', array['Pon los objetos en una mesa.', 'Toquen cada uno y digan si es suave, áspero, frío o liso.', 'Que cierre los ojos.', 'Dale uno y que adivine cuál es.']::text[], 'Pregúntale cuál le gusta más y por qué.', true),
  ('la-tortuga-tranquila', 'La tortuga tranquila', 'Meterse en el caparazón y respirar para calmarse.', 'Una forma sencilla de calmarse: hacerse bolita como tortuga y respirar despacio.', 3, 5, 5, 'tranquilo', 'cualquier', '{}'::text[], array['nada']::text[], true, 'Nada.', array['Cuéntale que las tortugas se esconden en su caparazón cuando necesitan calma.', 'Hagan bolita juntos en el piso.', 'Respiren despacio contando hasta 4.', 'Salgan del caparazón muy despacio.']::text[], 'Practíquenlo cuando esté tranquilo: así lo usará cuando esté enojado.', true),
  ('bingo-de-la-casa', 'Bingo de la casa', 'Un tablero con dibujos de cosas para encontrar.', 'Dibuja un tablero con 6 objetos de la casa y que tu hijo los busque y los tache.', 4, 5, 15, 'aprender', 'casa', array['papel', 'colores']::text[], array['papel', 'colores']::text[], false, '5 minutos.', array['Divide una hoja en 6 cuadros.', 'Dibuja en cada uno algo de la casa: una cuchara, un zapato, un libro.', 'Que busque cada objeto.', 'Cuando lo encuentre, que tache el cuadro.']::text[], 'Haz un tablero para cada cuarto de la casa.', true),
  ('carta-a-la-abuela', 'Carta a la abuela', 'Un dibujo y unas palabras para alguien que quiere.', 'Hagan juntos una carta con dibujos para un familiar y entréguenla o envíenle una foto.', 4, 5, 15, 'crear', 'casa', array['papel', 'colores', 'un sobre opcional']::text[], array['papel', 'colores']::text[], true, 'Nada.', array['Pregúntale a quién quiere escribirle.', 'Que haga un dibujo para esa persona.', 'Escribe lo que te dicte.', 'Que firme con su nombre o una huella.']::text[], 'Si no la pueden entregar, tómale una foto y envíala.', true),
  ('cohete-de-carton', 'Cohete de cartón', 'Un tubo de papel higiénico listo para despegar.', 'Conviertan un tubo de papel higiénico en un cohete con alas y fuego de papel.', 4, 5, 30, 'crear', 'casa', array['tubo de papel higiénico', 'papel', 'colores', 'cinta']::text[], array['carton', 'papel', 'colores', 'cinta']::text[], true, '2 minutos.', array['Que pinte el tubo de su color favorito.', 'Hagan un cono de papel para la punta.', 'Peguen tiras rojas y amarillas abajo como fuego.', 'Cuenten 3, 2, 1 y despeguen.']::text[], 'Peguen una foto de su cara en una ventanita: él es el astronauta.', true),
  ('lanzar-al-balde', 'Lanzar al balde', 'Medias enrolladas y un balde que se aleja cada vez.', 'Lancen medias enrolladas a un balde. Cada acierto, el balde se aleja un paso.', 4, 5, 15, 'moverse', 'casa', array['medias enrolladas', 'un balde o caja']::text[], array['nada']::text[], false, '1 minuto.', array['Pon el balde a dos pasos.', 'Que lance 5 medias.', 'Si mete 3, aleja el balde un paso.', 'Cuenten hasta dónde llegó.']::text[], 'Pruébenlo con la mano que no usa.', true),
  ('que-falta', '¿Qué falta?', 'Cinco objetos, una cobija y uno desaparece.', 'Pon cinco objetos en la mesa, cúbrelos y quita uno. Tu hijo adivina cuál falta.', 4, 5, 5, 'aprender', 'casa', array['5 objetos pequeños', 'una cobija o trapo']::text[], array['nada']::text[], false, 'Nada.', array['Pon 5 objetos y que los mire bien.', 'Cúbrelos con el trapo.', 'Quita uno sin que vea.', 'Destapa y que adivine cuál falta.']::text[], 'Sube a 6 o 7 objetos cuando lo domine.', true),
  ('chef-por-un-dia', 'Chef por un día', 'Preparar su propio sándwich paso a paso.', 'Tu hijo prepara su merienda con ingredientes que tú le dejas listos.', 4, 5, 15, 'juntos', 'casa', array['pan', 'ingredientes para el sándwich', 'un cuchillo sin punta', 'un plato']::text[], array['nada']::text[], true, '5 minutos.', array['Lávense las manos.', 'Pon los ingredientes en platos pequeños.', 'Que arme su sándwich solo.', 'Siéntense a comer lo que preparó.']::text[], 'Déjale untar con el cuchillo sin punta: le encanta sentirse grande.', true),
  ('noticiero-en-casa', 'Noticiero en casa', 'Un cepillo como micrófono y las noticias del día.', 'Tu hijo presenta las noticias de la casa con un micrófono de juguete.', 4, 5, 15, 'juntos', 'casa', array['un cepillo o control como micrófono']::text[], array['nada']::text[], false, 'Nada.', array['Arma una mesa como estudio de televisión.', 'Dale el micrófono.', 'Que cuente qué pasó hoy en la casa.', 'Hazle preguntas como periodista.']::text[], 'Grábalo con el celular y véanlo juntos.', true),
  ('huellas-de-pies', 'Huellas de pies', 'Pies pintados que caminan sobre papel.', 'Pinten las plantas de los pies con témpera y caminen sobre papel largo.', 4, 5, 15, 'crear', 'casa', array['papel largo', 'témperas', 'un plato', 'una toalla húmeda']::text[], array['papel', 'colores']::text[], true, '3 minutos.', array['Pon el papel en el piso y la toalla al final.', 'Pon pintura en el plato.', 'Que pise la pintura y camine sobre el papel.', 'Límpiense los pies en la toalla.']::text[], 'Hazlo en el patio o sobre bolsas plásticas para cuidar el piso.', true),
  ('el-limbo', 'El limbo', 'Pasar por debajo de un palo de escoba sin tocarlo.', 'Sostén un palo de escoba y que tu hijo pase por debajo. Cada vez, un poco más abajo.', 4, 5, 5, 'moverse', 'casa', array['un palo de escoba']::text[], array['nada']::text[], true, 'Nada.', array['Sostén el palo a la altura de su pecho.', 'Que pase por debajo sin tocarlo.', 'Bájalo un poco cada vuelta.', 'Pongan música para hacerlo más divertido.']::text[], 'Sostén el palo con suavidad para que no se golpee.', true),
  ('caras-de-plastilina', 'Caras de plastilina', 'Tapas, palitos y plastilina para crear personajes.', 'Con plastilina y objetos pequeños, tu hijo crea caras graciosas sobre la mesa.', 4, 5, 15, 'solo', 'casa', array['plastilina', 'tapas', 'palitos']::text[], array['plastilina']::text[], false, 'Nada.', array['Que haga un círculo grande con plastilina.', 'Que use tapas como ojos y una tira como boca.', 'Que le ponga pelo con palitos.', 'Pónganle nombre al personaje.']::text[], 'Tómale foto a cada personaje antes de deshacerlo.', true),
  ('contar-con-frijoles', 'Contar con frijoles', 'Vasos con números y frijoles para llenar.', 'Marca vasos con números y que tu hijo ponga en cada uno la cantidad exacta de frijoles.', 4, 5, 15, 'aprender', 'casa', array['5 vasos', 'frijoles secos', 'papel', 'cinta']::text[], array['papel', 'cinta']::text[], true, '3 minutos.', array['Pega en cada vaso un papel con un número del 1 al 5.', 'Pon los frijoles en un plato.', 'Que ponga en cada vaso los frijoles que dice el número.', 'Cuenten juntos para revisar.']::text[], 'Supervisa siempre: los frijoles son pequeños.', true),
  ('carrera-de-cangrejos', 'Carrera de cangrejos', 'Caminar de lado, boca arriba, como cangrejo.', 'Una carrera divertida caminando como cangrejo, apoyados en manos y pies.', 4, 5, 5, 'moverse', 'cualquier', '{}'::text[], array['nada']::text[], false, 'Nada.', array['Muéstrale la postura: sentado, manos atrás, cola arriba.', 'Marquen una meta cerca.', 'Hagan la carrera de cangrejos.', 'Prueben ir para atrás y de lado.']::text[], 'Quítenle obstáculos al camino antes de empezar.', true),
  ('sembrar-un-frijol', 'Sembrar un frijol', 'Un vaso, algodón y un frijol que crece cada día.', 'Siembren un frijol en algodón húmedo y obsérvenlo crecer durante la semana.', 4, 5, 15, 'aprender', 'casa', array['un vaso transparente', 'algodón', 'un frijol', 'agua']::text[], array['nada']::text[], true, 'Nada.', array['Pon algodón en el fondo del vaso.', 'Que ponga el frijol encima.', 'Mojen el algodón sin encharcarlo.', 'Pongan el vaso cerca de la ventana y revísenlo cada día.']::text[], 'Hagan un dibujo cada día para ver cómo cambia.', true),
  ('paseo-de-los-sentidos', 'Paseo de los sentidos', 'Una caminata para ver, oír y oler con atención.', 'Salgan a caminar y busquen cosas con cada sentido: 5 que ven, 4 que oyen, 3 que tocan.', 4, 5, 15, 'tranquilo', 'afuera', '{}'::text[], array['nada']::text[], true, 'Nada.', array['Salgan a caminar por el barrio o el parque.', 'Busquen 5 cosas que puedan ver.', 'Paren y escuchen 4 sonidos.', 'Toquen 3 cosas distintas: una hoja, una piedra, un tronco.']::text[], 'Caminen despacio: el objetivo es fijarse, no llegar.', true),
  ('collage-de-hojas', 'Collage de hojas', 'Hojas secas que se vuelven animales y caras.', 'Recojan hojas secas y armen figuras pegándolas en papel.', 4, 5, 30, 'crear', 'cualquier', array['hojas secas', 'papel', 'pegante en barra']::text[], array['papel']::text[], true, 'Recoger las hojas, 10 minutos.', array['Recojan hojas de varios tamaños.', 'Pónganlas sobre el papel para formar un animal o una cara.', 'Péguenlas con pegante.', 'Dibujen los detalles que falten.']::text[], 'Las hojas secas se pegan mejor que las verdes.', true),
  ('mi-nombre-con-cinta', 'Mi nombre con cinta', 'Las letras de su nombre en el piso para caminar encima.', 'Escriban el nombre de tu hijo con cinta en el piso y recórranlo letra por letra.', 5, 5, 15, 'aprender', 'casa', array['cinta de enmascarar']::text[], array['cinta']::text[], true, '5 minutos.', array['Escribe su nombre en grande con cinta en el piso.', 'Digan juntos cada letra.', 'Que camine sobre cada letra diciendo su nombre.', 'Prueben con el nombre de otra persona de la familia.']::text[], 'Hazlo también con números del 1 al 10.', true),
  ('juego-de-mesa-casero', 'Juego de mesa casero', 'Un tablero de cartón con casillas, premios y castigos.', 'Diseñen juntos un juego de mesa con casillas en cartón y jueguen la primera partida.', 5, 5, 30, 'juntos', 'casa', array['cartón', 'colores', 'tapas como fichas', 'un dado o papelitos con números']::text[], array['carton', 'colores']::text[], true, 'Nada.', array['Dibujen un camino de 20 casillas en el cartón.', 'Pinten algunas casillas especiales: avanza 2, retrocede 1.', 'Usen tapas como fichas.', 'Jueguen la primera partida.']::text[], 'Que él invente las reglas de las casillas especiales.', true),
  ('veterinaria-de-peluches', 'Veterinaria de peluches', 'Peluches enfermos y un veterinario que los cura.', 'Tu hijo es el veterinario y cura a los peluches con curitas de papel.', 5, 5, 30, 'juntos', 'casa', array['peluches', 'papel', 'cinta', 'una caja como consultorio']::text[], array['papel', 'cinta']::text[], false, '2 minutos.', array['Arma un consultorio con una caja y una silla.', 'Haz curitas de papel con cinta.', 'Tú llevas los peluches enfermos.', 'Que los revise, los cure y les dé una receta.']::text[], 'Sirve para hablar de ir al médico sin miedo.', true),
  ('volcan-casero', 'Volcán casero', 'Bicarbonato y vinagre para una erupción de espuma.', 'Un experimento sencillo: mezclar bicarbonato y vinagre para que salga espuma como un volcán.', 5, 5, 15, 'aprender', 'casa', array['bicarbonato', 'vinagre', 'un vaso', 'una bandeja', 'colorante opcional']::text[], array['nada']::text[], true, '2 minutos.', array['Pon el vaso en la bandeja.', 'Echa dos cucharadas de bicarbonato.', 'Que vierta un chorrito de vinagre.', 'Miren la erupción y repitan.']::text[], 'Pregúntale antes qué cree que va a pasar.', true),
  ('tiro-al-blanco', 'Tiro al blanco', 'Un blanco de cinta en la pared y bolas de papel.', 'Hagan un blanco con cinta en la pared y lancen bolas de papel para sumar puntos.', 5, 5, 15, 'moverse', 'casa', array['cinta', 'papel']::text[], array['cinta', 'papel']::text[], false, '3 minutos.', array['Haz con cinta tres círculos en la pared, uno dentro de otro.', 'Pon puntos: 1, 2 y 3 en el centro.', 'Hagan bolas de papel.', 'Lancen por turnos y sumen los puntos.']::text[], 'Sumar los puntos es práctica de matemáticas sin que lo note.', true),
  ('adivinanzas', 'Adivinanzas', 'Pistas cortas para adivinar animales y objetos.', 'Por turnos, den pistas de un objeto o animal hasta que el otro adivine.', 5, 5, 5, 'tranquilo', 'cualquier', '{}'::text[], array['nada']::text[], false, 'Nada.', array['Piensa en algo: tiene cuatro patas y dice miau.', 'Da una pista a la vez.', 'Que adivine.', 'Cambien de turno y que él te ponga una adivinanza.']::text[], 'Perfecto para el carro o una fila larga.', true),
  ('puente-de-papel', 'Puente de papel', '¿Cuántas monedas aguanta un puente de papel?', 'Hagan un puente con una hoja entre dos vasos y prueben cuántas monedas resiste.', 5, 5, 15, 'aprender', 'casa', array['hojas de papel', '2 vasos', 'monedas']::text[], array['papel']::text[], true, 'Nada.', array['Pon la hoja plana sobre los dos vasos.', 'Pongan monedas una por una hasta que se caiga.', 'Ahora doblen la hoja como acordeón.', 'Prueben otra vez y comparen.']::text[], 'Pregúntale por qué cree que el acordeón aguanta más.', true),
  ('desfile-de-disfraces', 'Desfile de disfraces', 'Ropa de los grandes y una pasarela en la sala.', 'Con ropa vieja, sombreros y cobijas, tu hijo arma su disfraz y desfila.', 5, 5, 30, 'juntos', 'casa', array['ropa de adultos', 'sombreros', 'cobijas']::text[], array['nada']::text[], false, '2 minutos.', array['Pon la ropa en el piso.', 'Que arme un disfraz y le ponga nombre.', 'Hagan una pasarela con cinta o cojines.', 'Presenta a tu hijo como en un desfile.']::text[], 'Tómale fotos y hagan un álbum de personajes.', true),
  ('mi-primer-comic', 'Mi primer cómic', 'Una historia en tres cuadros dibujados.', 'Divide una hoja en tres cuadros y que tu hijo dibuje una historia: inicio, problema y final.', 5, 5, 30, 'solo', 'casa', array['papel', 'colores']::text[], array['papel', 'colores']::text[], false, '1 minuto.', array['Divide la hoja en tres cuadros.', 'Que piense en un personaje.', 'Que dibuje qué pasa al principio, el problema y cómo termina.', 'Que te cuente la historia.']::text[], 'Escribe tú lo que dice cada personaje en globos.', true),
  ('la-golosa', 'La golosa', 'El juego de siempre, con cinta en el piso de la casa.', 'Arma una golosa con cinta en el piso y jueguen con una tapa.', 5, 5, 15, 'moverse', 'casa', array['cinta de enmascarar', 'una tapa']::text[], array['cinta']::text[], false, '5 minutos.', array['Haz con cinta las casillas del 1 al 8.', 'Escribe los números en papel o con cinta.', 'Lanza la tapa a una casilla.', 'Salta en un pie sin pisar la casilla de la tapa.']::text[], 'Si un pie es difícil, que salte con los dos.', true),
  ('como-me-siento', '¿Cómo me siento hoy?', 'Dibujar caras de emociones y hablar del día.', 'Dibujen caras de distintas emociones y que tu hijo elija cómo se siente hoy.', 5, 5, 15, 'tranquilo', 'casa', array['papel', 'colores']::text[], array['papel', 'colores']::text[], true, 'Nada.', array['Dibujen juntos 4 caras: feliz, triste, enojado y asustado.', 'Que señale cómo se siente hoy.', 'Pregúntale qué lo hizo sentir así.', 'Cuéntale tú cómo te sientes.']::text[], 'Escucha sin corregir: lo importante es que lo diga.', true),
  ('rampa-para-carritos', 'Rampa para carritos', 'Un cartón, unos libros y carreras de carritos.', 'Arma una rampa con cartón y libros y prueben qué carrito llega más lejos.', 5, 5, 15, 'aprender', 'casa', array['un cartón largo', 'libros', 'carritos de juguete']::text[], array['carton']::text[], false, '2 minutos.', array['Apoya el cartón sobre una pila de libros.', 'Suelten dos carritos al mismo tiempo.', 'Miren cuál llega más lejos.', 'Suban o bajen la rampa y vuelvan a probar.']::text[], 'Pregúntale qué pasa si la rampa es más alta.', true),
  ('perrito-de-papel', 'Perrito de papel', 'Un origami fácil: un perrito en tres dobleces.', 'Doblen una hoja cuadrada para hacer la cara de un perrito y dibújenle los ojos.', 5, 5, 15, 'crear', 'casa', array['una hoja cuadrada', 'marcadores']::text[], array['papel', 'colores']::text[], true, 'Nada.', array['Dobla la hoja en triángulo.', 'Dobla las dos puntas de los lados hacia abajo: son las orejas.', 'Dobla la punta de abajo hacia arriba.', 'Que le dibuje los ojos y la nariz.']::text[], 'Haz uno tú al mismo tiempo para que te copie paso a paso.', true),
  ('veo-veo', 'Veo veo', 'Una cosita que empieza por la letra...', 'El juego de siempre: uno escoge algo que ve y da la primera letra o el color.', 5, 5, 5, 'tranquilo', 'cualquier', '{}'::text[], array['nada']::text[], false, 'Nada.', array['Escoge algo que ambos puedan ver.', 'Di: veo veo una cosita de color rojo.', 'Que adivine qué es.', 'Cambien de turno.']::text[], 'Con letras practica sonidos; con colores es más fácil.', true),
  ('picnic-en-la-sala', 'Picnic en la sala', 'Un mantel en el piso y la merienda con peluches.', 'Hagan un picnic en la sala con mantel, merienda y peluches invitados.', 5, 5, 30, 'juntos', 'casa', array['un mantel o toalla', 'la merienda', 'peluches']::text[], array['nada']::text[], false, '5 minutos.', array['Extiendan el mantel en el piso.', 'Que invite a sus peluches.', 'Sirvan la merienda en platos pequeños.', 'Cuenten historias mientras comen.']::text[], 'Si hace buen tiempo, háganlo en el balcón o el patio.', true),
  ('atrapa-la-cola', 'Atrapa la cola', 'Un pañuelo en el pantalón y a correr.', 'Cada uno se pone un pañuelo como cola y trata de quitarle la cola al otro.', 5, 5, 5, 'moverse', 'cualquier', array['2 pañuelos o medias']::text[], array['nada']::text[], false, 'Nada.', array['Pónganse el pañuelo en la parte de atrás del pantalón.', 'A la cuenta de tres, intenten quitarle la cola al otro.', 'Gana quien atrape primero.', 'Jueguen varias rondas.']::text[], 'Despejen el espacio de muebles con esquinas.', true),
  ('ritmo-con-vasos', 'Ritmo con vasos', 'Golpes, palmas y un vaso que pasa de mano en mano.', 'Inventen ritmos con palmas y golpes de vaso en la mesa y repítanlos por turnos.', 5, 5, 15, 'juntos', 'casa', array['un vaso plástico por persona']::text[], array['nada']::text[], false, 'Nada.', array['Haz un ritmo corto: dos palmas y un golpe de vaso.', 'Que lo repita.', 'Agrega un paso más cada ronda.', 'Que él invente un ritmo para ti.']::text[], 'Es un juego de memoria y coordinación a la vez.', true)
