-- PLANECITOS · 60 actividades nuevas (para llegar a 100)
-- Ejecutar en Supabase > SQL Editor, DESPUÉS de 0003_actividades_nuevas.sql

on conflict (slug) do nothing;

-- Revisión: total por edad mínima (debe sumar 100)
select min_age, count(*) as total, count(*) filter (where premium) as premium
from public.activities group by min_age order by min_age;
